import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (processing fee only)");
    it.todo("a sword → base premium 100 G");
    it.todo("an amulet → base premium 60 G");
    it.todo("a staff → base premium 80 G");
    it.todo("a potion → base premium 40 G");
    it.todo("a single rune → base premium 25 G");
    it.todo("a single moonstone → base premium 25 G");
    it.todo("a sword and an amulet → policy base premium 160 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("a cursed sword → 50 G curse surcharge (50 % of the item's base premium)");
    it.todo("a sword with enchantment 5 → 30 G high-enchantment surcharge");
    it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("a cursed sword with enchantment 5 → both surcharges apply");
    it.todo(
      "a cursed sword and a plain amulet → policy base 160 G, curse adds 50 G (50 % of the sword only) → 210 G before further modifiers and fee",
    );
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("a first quote carries the 10 % initial assessment surcharge");
    it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
    it.todo(
      "the first insurance surcharge still applies on a follow-up contract (each item is treated as a first insurance)",
    );
  });

  describe("quote — rounding in the MHPCO's favour", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed steel sword, enchantment 7 → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo(
      "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement then deductible)",
    );
    it.todo(
      "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)",
    );
    it.todo(
      "dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)",
    );
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)",
    );
    it.todo("a damage amount below the deductible does not produce a negative payout");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo(
      "two sword damage entries against a policy with two swords → each is a separate damage with its own deductible",
    );
  });

  describe("claim — payout cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo(
      "a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)",
    );
    it.todo(
      "a policy covering a sword and 3 runes → insurance sum 1750 G (the block discount affects the premium only)",
    );
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
    it.todo(
      "sword policy, second successive claim of 1500 G → payout 600 G, remaining cap 0 G (reduced to the remaining cap)",
    );
  });

  describe("claim — rounding in the MHPCO's favour", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("errors", () => {
    it.todo("a quote item with an unknown type (e.g. broomstick) is rejected");
    it.todo("a claim damaging an item that is not part of the policy is rejected");
    it.todo("a claim damaging an item of unknown type is rejected");
    it.todo(
      "a claim with more damage entries of a type than the policy covers (two swords, one insured) is rejected",
    );
    it.todo("a claim damage entry with amount -200 is rejected");
  });

  describe("scenario processing", () => {
    it.todo("results are returned in the same order and length as the input steps");
    it.todo(
      "a claim refers to the policy created by an earlier quote step via its zero-based step index",
    );
  });
});

