    it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
    it.todo(
      "the first insurance surcharge still applies on a follow-up contract (each item is treated as a first insurance)",
    );
  });

  describe("quote — rounding in the MHPCO's favour", () => {
