    );
    it.todo(
      "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)",
    );
    it.todo(
      "dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)",
    );
  });

