const FIRST_INSURANCE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

// Percentages are applied as exact integer fractions; floating-point
// multiplication drifts (100 * 1.1 === 110.00000000000001) and the spec
// rounds only at the very end.
const quote = ({ items }: QuoteStep): StepResult => {
  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const withSurcharge = (base * (100 + FIRST_INSURANCE_PERCENT)) / 100;

  return { premium: Math.ceil(withSurcharge + PROCESSING_FEE) };
};

