const CURSE_PERCENT = 50;

const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

// Every modifier is a percentage of a base premium, and they are SUMMED rather
// than compounded: the spec's worked example reads
// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
// so the first-insurance 10 % is taken on the policy base, not on the
// curse-inflated amount.
const itemSurcharges = (items: Item[]): number =>
  items
    .filter((item) => item.cursed)
    .reduce((total, item) => total + percentOf(BASE_PREMIUMS[item.type], CURSE_PERCENT), 0);

const quote = ({ items }: QuoteStep): StepResult => {
  const policyBase = policyBasePremium(items);
  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
  const total = policyBase + itemSurcharges(items) + firstInsurance + PROCESSING_FEE;

  return { premium: Math.ceil(total) };
};

