export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// Percentages MUST go through this helper. Applying them as exact integer
// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
// at the very end that drift becomes a whole extra G.
const addPercent = (amount: number, percent: number): number =>
  (amount * (100 + percent)) / 100;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

