export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);

  return counts;
};

const basePremiumForType = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)]
    .map(([type, count]) => basePremiumForType(type, count))
    .reduce((total, premium) => total + premium, 0);

const CURSE_PERCENT = 50;

// Percentages MUST go through this helper. Multiplying first and dividing by
// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
// 110.00000000000001 — and since the spec rounds premiums UP at the very end
// that drift becomes a whole extra G.
const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

const itemSurcharges = (items: Item[]): number =>
  items
    .filter((item) => item.cursed)
    .reduce((total, item) => total + percentOf(BASE_PREMIUMS[item.type], CURSE_PERCENT), 0);

// Every modifier is a percentage of a base premium, and they are SUMMED rather
// than compounded: the spec's worked example reads
// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
// so the first-insurance 10 % is taken on the policy base, not on the
// curse-inflated amount.
const quote = ({ items }: QuoteStep): StepResult => {
  const policyBase = policyBasePremium(items);
  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
  const total = policyBase + itemSurcharges(items) + firstInsurance + PROCESSING_FEE;

  return { premium: Math.ceil(total) };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
  results: scenario.steps.map((step) => quote(step as QuoteStep)),
});

