export const runScenario = (scenario: Scenario): ScenarioResult => {
  // Counts quote steps only: the follow-up discount is about contract number,
  // so interleaved claim steps must not advance it.
  let quotesSoFar = 0;

  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
  const results = scenario.steps.map((step) => {
    const result = quote(step as QuoteStep, scenario.customer, quotesSoFar > 0);
    quotesSoFar += 1;

    return result;
  });

  return { results };
};

