const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

interface Policy {
  items: Item[];
  remainingCap: number;
}

const openPolicy = (items: Item[]): Policy => ({
  items,
  remainingCap:
    CAP_MULTIPLIER * items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0),
});

const claim = ({ incident }: ClaimStep, policy: Policy): StepResult => {
  const payout = incident.damages.reduce(
    (total, damage) => total + (damage.amount - DEDUCTIBLE),
    0,
  );

  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: StepResult[] = [];
  const policies = new Map<number, Policy>();

  // Counts quote steps only: the follow-up discount is about contract number,
  // so interleaved claim steps must not advance it.
  let quotesSoFar = 0;

  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push(quote(step, scenario.customer, quotesSoFar > 0));
      policies.set(index, openPolicy(step.items));
      quotesSoFar += 1;

      return;
    }

    results.push(claim(step, policies.get(step.policy) as Policy));
  });

  return { results };
};

