        policy: 0,
        incident: { cause: "fire", damages: [{ itemType: "sword", amount: 600 }] },
      },
    ],
  });

  // The curse raises the premium to 165 but leaves the cap at 2 × 1000.
  expect(result.results).toEqual([{ premium: 165 }, { payout: 500, remainingCap: 1500 }]);
});

