        policy: 0,
        incident: { cause: "scratch", damages: [{ itemType: "sword", amount: 50 }] },
      },
    ],
  });

  expect(result.results).toEqual([{ premium: 115 }, { payout: 0, remainingCap: 2000 }]);
});

